class PersonalDataScreen extends ConsumerStatefulWidget{const PersonalDataScreen({super.key});@override ConsumerState<PersonalDataScreen> createState()=>_PersonalDataScreenState();}
class _PersonalDataScreenState extends ConsumerState<PersonalDataScreen>{final name=TextEditingController(),phone=TextEditingController(),code=TextEditingController();bool busy=false,otp=false,seeded=false;
@override void dispose(){name.dispose();phone.dispose();code.dispose();super.dispose();}
Future<void> _avatar()async{final x=await ImagePicker().pickImage(source:ImageSource.gallery,imageQuality:88,maxWidth:1600);if(x==null)return;setState(()=>busy=true);try{await ref.read(authRepositoryProvider).uploadAvatar(x.path);ref.invalidate(currentUserProvider);if(mounted)showSpikeToast(context,'تم تحديث الصورة');}catch(e){if(mounted)showSpikeToast(context,e.toString());}finally{if(mounted)setState(()=>busy=false);}}
Future<void> _saveName()async{if(name.text.trim().isEmpty)return;setState(()=>busy=true);try{await ref.read(authRepositoryProvider).updateProfile(name:name.text);ref.invalidate(currentUserProvider);if(mounted)showSpikeToast(context,'تم حفظ الاسم');}catch(e){if(mounted)showSpikeToast(context,e.toString());}finally{if(mounted)setState(()=>busy=false);}}
Future<void> _requestPhone()async{if(phone.text.trim().isEmpty)return;setState(()=>busy=true);try{await ref.read(authRepositoryProvider).requestPhoneChange(phone.text);if(mounted)setState(()=>otp=true);if(mounted)showSpikeToast(context,'تم إرسال رمز التحقق');}catch(e){if(mounted)showSpikeToast(context,e.toString());}finally{if(mounted)setState(()=>busy=false);}}
Future<void> _verifyPhone()async{if(code.text.trim().length!=6){showSpikeToast(context,'أدخل رمز التحقق المكوّن من 6 أرقام');return;}setState(()=>busy=true);try{await ref.read(authRepositoryProvider).verifyPhoneChange(code.text);ref.invalidate(currentUserProvider);if(mounted){setState(()=>otp=false);showSpikeToast(context,'تم تحديث رقم الجوال');}}catch(e){if(mounted)showSpikeToast(context,e.toString());}finally{if(mounted)setState(()=>busy=false);}}
@override Widget build(BuildContext context){final state=ref.watch(currentUserProvider),dark=Theme.of(context).brightness==Brightness.dark;return Scaffold(appBar:AppBar(title:const Text('الملف الشخصي'),centerTitle:true),body:state.when(loading:()=>const SpikeLoading(),error:(e,_)=>SpikeErrorState(message:e.toString(),onRetry:()=>ref.invalidate(currentUserProvider)),data:(u){if(u==null)return const SpikeEmptyState(message:'سجّل الدخول أولاً');if(!seeded){seeded=true;name.text='${u['name']??''}';phone.text='${u['phone']??''}';}final avatar='${u['avatar_url']??''}';return ListView(padding:SpikeSpacing.pageList,children:[Container(padding:SpikeSpacing.card,decoration:BoxDecoration(color:dark?spikeDarkPanel:spikePanel,borderRadius:BorderRadius.circular(SpikeRadius.card)),child:Column(children:[CircleAvatar(radius:38,backgroundColor:Theme.of(context).colorScheme.surface,backgroundImage:avatar.isEmpty?null:CachedNetworkImageProvider(avatar),child:avatar.isEmpty?const Icon(Icons.person_outline,size:32):null),const SizedBox(height:SpikeSpacing.sm),TextButton.icon(onPressed:busy?null:_avatar,icon:const Icon(LucideIcons.camera,size:17),label:const Text('تغيير الصورة')),Text('${u['email']??''}',style:Theme.of(context).textTheme.bodySmall)])),const SizedBox(height:SpikeSpacing.lg),const Text('الاسم',style:TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:SpikeSpacing.sm),TextField(controller:name,decoration:const InputDecoration(hintText:'الاسم الكامل')),const SizedBox(height:SpikeSpacing.sm),SizedBox(height:48,child:FilledButton(style:FilledButton.styleFrom(backgroundColor:spikeRed),onPressed:busy?null:_saveName,child:const Text('حفظ الاسم'))),const SizedBox(height:SpikeSpacing.xl),const Text('رقم الجوال',style:TextStyle(fontWeight:FontWeight.w800)),const SizedBox(height:SpikeSpacing.sm),TextField(controller:phone,keyboardType:TextInputType.phone,enabled:!otp,decoration:const InputDecoration(hintText:'رقم الجوال الجديد')),const SizedBox(height:SpikeSpacing.sm),if(!otp)SizedBox(height:48,child:OutlinedButton.icon(onPressed:busy?null:_requestPhone,icon:const Icon(LucideIcons.send,size:18),label:const Text('إرسال رمز التحقق')))else...[TextField(controller:code,keyboardType:TextInputType.number,maxLength:6,decoration:const InputDecoration(hintText:'رمز التحقق')),const SizedBox(height:SpikeSpacing.sm),SizedBox(height:48,child:FilledButton(style:FilledButton.styleFrom(backgroundColor:spikeRed),onPressed:busy?null:_verifyPhone,child:const Text('تأكيد الرقم'))),const SizedBox(height:SpikeSpacing.xs),TextButton(onPressed:busy?null:_requestPhone,child:const Text('إعادة إرسال الرمز')),TextButton(onPressed:busy?null:()=>setState(()=>otp=false),child:const Text('تغيير الرقم'))]]); }));}
}
